// DAILY BADGE
// ==========================================

function updateDailyBadge() {

    // The result is now shown in a modal when the player taps the
    // Daily Challenge button (see openDailyStatusModal), so this
    // element is kept empty rather than showing a persistent label.

    const badge = document.getElementById("dailyStatus");

    if (!badge) return;

    badge.textContent = "";

}


// ==========================================
// STATS
// ==========================================

function showStats() {

    document.getElementById("menuScreen").classList.remove("active");

    document.getElementById("statsScreen").classList.add("active");

    updateStats();

}


function updateStats() {

    const gamesPlayed =
        Number(localStorage.getItem("gamesPlayed")) || 0;

    const gamesWon =
        Number(localStorage.getItem("gamesWon")) || 0;

    const streak =
        Number(localStorage.getItem("streak")) || 0;

    const winRate =
        gamesPlayed === 0
            ? 0
            : Math.round((gamesWon / gamesPlayed) * 100);

    document.getElementById("gamesPlayed").textContent =
        gamesPlayed;

    document.getElementById("gamesWon").textContent =
        gamesWon;

    document.getElementById("winRate").textContent =
        winRate + "%";

    document.getElementById("currentStreak").textContent =
        streak;

    const dailyStreak =
        Number(localStorage.getItem("dailyStreak")) || 0;

    const dailyStreakEl = document.getElementById("dailyStreak");

    if (dailyStreakEl) dailyStreakEl.textContent = dailyStreak;

    renderAchievements();

}


// ==========================================
// PLAYER SEARCH
// ==========================================

const input =
    document.getElementById("playerInput");

const suggestions =
    document.getElementById("suggestions");

let activeSuggestionIndex = -1;


function highlightMatch(name, search) {

    const idx = name.toLowerCase().indexOf(search);

    if (idx === -1) return name;

    return (
        name.slice(0, idx) +
        `<mark>${name.slice(idx, idx + search.length)}</mark>` +
        name.slice(idx + search.length)
    );

}


input.addEventListener("input", function () {

    const search =
        input.value.toLowerCase().trim();

    suggestions.innerHTML = "";

    activeSuggestionIndex = -1;

    if (search === "") {
        return;
    }

    const matches =
        players
            .filter(player =>
                player.name
                    .toLowerCase()
                    .includes(search)
            )
            .slice(0, 6);


    matches.forEach(player => {

        const div =
            document.createElement("div");

        div.className = "suggestion";

        div.innerHTML = highlightMatch(player.name, search);

        div.onclick = function () {

            input.value = player.name;

            suggestions.innerHTML = "";

            sfxSelect();

            input.focus();

        };

        suggestions.appendChild(div);

    });

});


function highlightSuggestion(index) {

    const items = suggestions.querySelectorAll(".suggestion");

    items.forEach(el => el.classList.remove("highlighted"));

    if (items[index]) {
        items[index].classList.add("highlighted");
        items[index].scrollIntoView({ block: "nearest" });
    }

}


// ==========================================
// GUESS
// ==========================================

function guessPlayer() {

    if (typeof mp !== "undefined" && mp.active) {
        mpSubmitGuess();
        return;
    }

    if (!secretPlayer) {
        return;
    }

    if (attempts >= maxAttempts) {
        return;
    }

    const playerName =
        input.value.trim();


    const guessedPlayer =
        players.find(
            player =>
                player.name.toLowerCase() ===
                playerName.toLowerCase()
        );


    if (!guessedPlayer) {

        showMessage(
            "❌ Choose a footballer from the suggestions."
        );

        return;
    }


    attempts++;

    suggestions.innerHTML = "";

    createGuessRow(guessedPlayer);

    input.value = "";

    document.getElementById("attemptsLeft").textContent =
        maxAttempts - attempts;

    updateProgressBar();


    // ======================================
    // WIN
    // ======================================

    if (
        guessedPlayer.name ===
        secretPlayer.name
    ) {

        showMessage(
            t("amazing", { player: secretPlayer.name })
        );

        input.disabled = true;

        recordGame(true);

        launchConfetti();

        sfxWin();

        hapticPulse([20, 40, 20]);

        showShareButton();

        const rows = document.querySelectorAll("#guesses .guess-row");

        if (rows.length) {
            rows[rows.length - 1].classList.add("winning-row");
        }

        return;
    }


    // ======================================
    // LOSE
    // ======================================

    if (attempts >= maxAttempts) {

        showMessage(
            t("gameOver", { player: secretPlayer.name })
        );

        input.disabled = true;

        recordGame(false);

        sfxLose();

        hapticPulse(60);

        showShareButton();

        return;
    }


    showMessage(
        t("notThisOne", { amount: maxAttempts - attempts })
    );

    sfxWrong();

    shakeMessage();

}


// ==========================================
// CREATE GUESS ROW
// ==========================================

function createGuessRow(player) {

    const container =
        document.getElementById("guesses");


    const row =
        document.createElement("div");

    row.className = "guess-row";


    // PLAYER

    row.appendChild(
        createCell(
            player.name,
            "guess-cell"
        )
    );


    // COUNTRY

    const countryStatus =
        player.country === secretPlayer.country
            ? "correct"
            : "wrong";

    row.appendChild(
        createCell(
            player.country,
            countryStatus,
            flagFor(player.country)
        )
    );


    // CLUB

    const clubStatus =
        player.club === secretPlayer.club
            ? "correct"
            : "wrong";

    row.appendChild(
        createCell(
            player.club,
            clubStatus
        )
    );


    // LEAGUE

    const leagueStatus =
        player.league === secretPlayer.league
            ? "correct"
            : "wrong";

    row.appendChild(
        createCell(
            player.league,
            leagueStatus
        )
    );


    // POSITION

    const positionStatus =
        player.position === secretPlayer.position
            ? "correct"
            : "wrong";

    row.appendChild(
        createCell(
            player.position,
            positionStatus
        )
    );


    // AGE

    let ageClass = "wrong";

    let ageArrow = "";


    if (player.age === secretPlayer.age) {

        ageClass = "correct";

    } else {

        ageClass =
            Math.abs(
                player.age - secretPlayer.age
            ) <= 2
                ? "close"
                : "wrong";


        ageArrow =
            player.age < secretPlayer.age
                ? " ⬆️"
                : " ⬇️";

    }


    row.appendChild(
        createCell(
            player.age + ageArrow,
            ageClass
        )
    );


    // FOOT

    const footStatus =
        player.foot === secretPlayer.foot
            ? "correct"
            : "wrong";

    row.appendChild(
        createCell(
            player.foot,
            footStatus
        )
    );


    container.appendChild(row);

    guessHistory.push([
        countryStatus,
        clubStatus,
        leagueStatus,
        positionStatus,
        ageClass,
        footStatus
    ]);

    playCellCascade([
        countryStatus,
        clubStatus,
        leagueStatus,
        positionStatus,
        ageClass,
        footStatus
    ]);

}

function playCellCascade(statuses) {

    statuses.forEach((status, i) => {

        const delay = i * 0.06;

        if (status === "correct") {
            playTone(880, delay, 0.1, "triangle", 0.1);
        } else if (status === "close") {
            playTone(600, delay, 0.08, "triangle", 0.08);
        }

    });

    if (statuses.includes("correct")) {
        hapticPulse(12);
    }

}


// ==========================================
// CREATE CELL
// ==========================================

function createCell(text, className, flagHtml) {

    const cell =
        document.createElement("div");

    cell.className =
        `guess-cell ${className}`;

    if (flagHtml) {
        cell.insertAdjacentHTML("beforeend", flagHtml);
    }

    cell.appendChild(
        document.createTextNode(text)
    );

    return cell;

}


// ==========================================
// MESSAGE
// ==========================================

function showMessage(message) {

    document.getElementById("message").textContent =
        message;

}


// ==========================================
// SAVE STATS
// ==========================================

function recordGame(won) {

    let gamesPlayed =
        Number(localStorage.getItem("gamesPlayed")) || 0;

    let gamesWon =
        Number(localStorage.getItem("gamesWon")) || 0;

    let streak =
        Number(localStorage.getItem("streak")) || 0;


    gamesPlayed++;


    if (won) {

        gamesWon++;

        streak++;

    } else {

        streak = 0;

    }


    localStorage.setItem(
        "gamesPlayed",
        gamesPlayed
    );

    localStorage.setItem(
        "gamesWon",
        gamesWon
    );

    localStorage.setItem(
        "streak",
        streak
    );

    let dailyStreak =
        Number(localStorage.getItem("dailyStreak")) || 0;

    if (isDaily) {

        localStorage.setItem("dailyDate", todayKey());

        localStorage.setItem("dailyWon", won ? "true" : "false");

        dailyStreak = won ? dailyStreak + 1 : 0;

        localStorage.setItem("dailyStreak", dailyStreak);

    }

    checkAchievements({
        won,
        gamesWon,
        streak,
        dailyStreak
    });

    if (won) {
        recordLeaderboardEntry(attempts, difficulty);
    }

}


