// Replace message texts while keeping original game logic.

const originalGuessPlayer = guessPlayer;

guessPlayer = function() {

    if (typeof mp !== "undefined" && mp.active) {
        mpSubmitGuess();
        return;
    }

    if (!secretPlayer || attempts >= maxAttempts) {
        return;
    }

    const playerName = input.value.trim();

    const guessedPlayer = players.find(
        player =>
            player.name.toLowerCase() ===
            playerName.toLowerCase()
    );

    if (!guessedPlayer) {

        showMessage(
            t("chooseSuggestion")
        );

        return;
    }

    originalGuessPlayer();

};


// ------------------------------------------
// TRANSLATED HINT
// ------------------------------------------

const originalUseHint = useHint;

useHint = function() {

    if (typeof mp !== "undefined" && mp.active) {
        mpUseHint();
        return;
    }

    if (!secretPlayer || hintUsed || input.disabled) return;

    originalUseHint();

    const hintText =
        document.getElementById("hintText");

    if (hintText) {

        const verbKey =
            secretPlayer.isLegend
                ? "hintLegend"
                : "hintNormal";

        hintText.innerHTML =
            t(verbKey, {
                flag: flagFor(secretPlayer.country),
                country: secretPlayer.country,
                league:
                    secretPlayer.hintLeague ||
                    secretPlayer.league
            });

    }

};


